text:
{
  "title": "سياسة الخصوصية وشروط الاستخدام لشركة أفق الحلول الرقمية",
  "planted": [
    {
      "slot": "p1",
      "text": "تحتفظ الشركة بحق استخدام البيانات الشخصية المجمعة من المستخدمين في أي أغراض تجارية تراها مناسبة لتطوير أعمالها، بما في ذلك الأغراض المستقبلية الجديدة التي يتم تحديدها لاحقاً دون الحاجة لإشعار مسبق أو الحصول على موافقة إضافية."
    },
    {
      "slot": "p2",
      "text": "تكتفي الشركة بنشر الخطوط العريضة لخدماتها دون تفصيل أنواع البيانات المصنفة أو آليات معالجتها وحفظها، على أن يتم توفير معلومات إضافية للمستخدم عند الطلب الخطي اللاحق لعملية التسجيل بحسب تقدير إدارة الخدمة."
    },
    {
      "slot": "p3",
      "text": "تُستخدم البيانات الصحية والمعلومات الحساسة الخاصة بالمستخدمين ضمن الحملات التسويقية المخصصة، وتتيح الشركة لكافة فرق العمل والإدارات التجارية صلاحية الاطلاع عليها لتحسين جودة المنتجات المعروضة."
    },
    {
      "slot": "p4",
      "text": "في حال وقوع أي اختراق أمني أو وصول غير مصرح به للبيانات، تلتزم الشركة بإخطار الجهة المختصة خلال الإطار الزمني المتعارف عليه، مع إشعار المتضررين إذا تبين أن الحادثة قد تمس بحقوقهم أو بياناتهم بشكل مباشر."
    },
    {
      "slot": "p5",
      "text": "تتمكن الشركة من إرسال التنبيهات والعروض الترويجية عبر القنوات الرقمية للمستخدم، وتوفر آلية تقنية ملائمة لإيقاف تلك الرسائل وفقاً للضوابط التشغيلية المعمول بها."
    }
  ],
  "neutral": [
    "تخضع جميع المعاملات المالية ورسوم الاشتراكات لسياسة التسعير المعلنة في المنصة، ويجب سداد المبالغ المستحقة في مواعيدها المحددة لضمان استمرار تقديم الخدمات دون انقطاع.",
    "تظل هذه الاتفاقية سارية المفعول طالما كان الحساب الخاص بالمستخدم نشطاً، ويحق لأي طرف إنهاء التعاقد بموجب إشعار خطي يوجه للطرف الآخر قبل موعد الإنهاء بمدة كافية.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو الخسائر التبعية الناتجة عن سوء استخدام الخدمات أو تعطل الشبكات لأسباب خارجة عن إرادتها التشغيلية.",
    "تُفسر هذه الشروط وتخضع لأنظمة القوانين المعمول بها في المملكة العربية السعودية، وفي حال النزاع تختص الجهات القضائية وحدها بالبت فيه.",
    "جميع حقوق الملكية الفكرية والعلامات التجارية والتصميمات والمحتوى المنشور على المنصة هي ملكية حصرية للشركة، ولا يجوز نسخها أو استغلالها دون إذن خطي مسبق.",
    "تُوجه كافة الإشعارات والخطابات الرسمية بين الطرفين عبر البريد الإلكتروني المسجل في المنصة، وتعتبر منتبة لأثرها القانوني فور إرسالها واستلام تأكيد الإرسال."
  ]
}
